let events=[];let filtered=[];let current=0;const albums=document.querySelector('#albums');const dialog=document.querySelector('#lightbox');let category='All';
function render(){const query=document.querySelector('input[type=search]').value.toLowerCase();filtered=events.filter(e=>(category==='All'||e.category===category)&&e.title.toLowerCase().includes(query));albums.innerHTML=filtered.map((e,i)=>`<button class="album" data-index="${i}" aria-label="View ${e.title}"><div class="image-wrap"><img loading="lazy" src="${e.image}" alt="${e.title} at Maharaja Ranjit Singh Police Public School"><span class="open-icon">↗</span></div><p class="category">${e.category.toUpperCase()} · ${e.year}</p><h3>${e.title}</h3><small>Explore event album →</small></button>`).join('');document.querySelector('#empty').hidden=filtered.length>0;albums.querySelectorAll('button').forEach(b=>b.onclick=()=>{current=Number(b.dataset.index);show();dialog.showModal()})}
function show(){const e=filtered[current];document.querySelector('#viewer-image').src=e.image;document.querySelector('#viewer-image').alt=e.title;document.querySelector('#viewer-title').textContent=e.title;document.querySelector('#viewer-category').textContent=e.category+' · '+e.year;document.querySelector('#viewer-source').href=e.url;document.querySelector('#viewer-count').textContent=`${current+1} / ${filtered.length}`}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{category=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});render()});document.querySelector('input[type=search]').oninput=render;document.querySelector('.close').onclick=()=>dialog.close();document.querySelector('#prev').onclick=()=>{current=(current-1+filtered.length)%filtered.length;show()};document.querySelector('#next').onclick=()=>{current=(current+1)%filtered.length;show()};dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('keydown',e=>{if(e.key==='ArrowRight')document.querySelector('#next').click();if(e.key==='ArrowLeft')document.querySelector('#prev').click()});const menu=document.querySelector('.menu');menu.onclick=()=>{const open=document.querySelector('nav').classList.toggle('open');menu.setAttribute('aria-expanded',String(open))};document.querySelectorAll('nav a').forEach(a=>a.onclick=()=>{document.querySelector('nav').classList.remove('open');menu.setAttribute('aria-expanded','false')});fetch('events.json').then(r=>r.json()).then(data=>{events=data;render()}).catch(()=>{albums.textContent='Please visit the school photo archive to explore event albums.'});

// Homepage carousel: three slides, advancing every three seconds.
const slides=[...document.querySelectorAll('.hero-slide')];const dots=[...document.querySelectorAll('.slide-dots button')];const carousel=document.querySelector('.hero-carousel');let slideIndex=0;let carouselTimer;let carouselPaused=false;let focusWithin=false;const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');
function setSlide(index){slideIndex=(index+slides.length)%slides.length;slides.forEach((slide,i)=>{const active=i===slideIndex;slide.classList.toggle('is-active',active);slide.inert=!active;slide.setAttribute('aria-hidden',String(!active));dots[i].classList.toggle('active',active);dots[i].setAttribute('aria-pressed',String(active))})}
function scheduleSlides(){clearInterval(carouselTimer);if(!carouselPaused&&!focusWithin&&!document.hidden&&!reducedMotion.matches)carouselTimer=setInterval(()=>setSlide(slideIndex+1),3000)}
function manualSlide(index){setSlide(index);scheduleSlides()}
document.querySelector('#slide-prev').onclick=()=>manualSlide(slideIndex-1);document.querySelector('#slide-next').onclick=()=>manualSlide(slideIndex+1);dots.forEach((dot,i)=>dot.onclick=()=>manualSlide(i));document.querySelector('#slide-pause').onclick=e=>{carouselPaused=!carouselPaused;e.currentTarget.textContent=carouselPaused?'▶':'Ⅱ';e.currentTarget.setAttribute('aria-label',carouselPaused?'Play slideshow':'Pause slideshow');e.currentTarget.setAttribute('aria-pressed',String(carouselPaused));scheduleSlides()};carousel.addEventListener('focusin',()=>{focusWithin=true;scheduleSlides()});carousel.addEventListener('focusout',e=>{if(!carousel.contains(e.relatedTarget)){focusWithin=false;scheduleSlides()}});document.addEventListener('visibilitychange',scheduleSlides);reducedMotion.addEventListener('change',scheduleSlides);scheduleSlides();
